class BaseForm {
  title() { return this; }
  body() { return this; }
  button1() { return this; }
  button2() { return this; }
}

export class ActionFormData extends BaseForm {
  constructor() { super(); this._buttons = 0; }
  button() { this._buttons++; return this; }
  async show() { return { canceled: false, selection: 0 }; }
}

export class MessageFormData extends BaseForm {
  async show() { return { canceled: false, selection: 0 }; }
}
